tc = matlab.unittest.TestCase.forInteractiveUse;
verifyClass(tc, int8(1), 'int8')
verifyClass(tc, 1, 'single')
m = containers.Map;
verifyInstanceOf(tc, m, 'handle')
verifyClass(tc, m, 'containers.Map')

tc = matlab.unittest.TestCase.forInteractiveUse;
p = [0.2 0.5 0.3];
verifyGreaterThanOrEqual(tc, p, 0)
verifyLessThanOrEqual(tc, p, 1)
verifyGreaterThan(tc, p, 0.25)

tc = matlab.unittest.TestCase.forInteractiveUse;
v = [3 1 2];
verifyReturnsTrue(tc, @() issorted(sort(v)))
verifyReturnsTrue(tc, @() issorted(v))

tc = matlab.unittest.TestCase.forInteractiveUse;
msg = sprintf('Saved %d rows to %s.', 12, 'out.csv');
verifySubstring(tc, msg, '12 rows')
verifySubstring(tc, msg, 'Rows')
verifyMatches(tc, 'AB-1234', '^[A-Z]{2}-\d{4}$')

tc = matlab.unittest.TestCase.forInteractiveUse;
m = containers.Map;
alias = m;
verifySameHandle(tc, alias, m)
verifyNotSameHandle(tc, containers.Map, m)
